package simu.manufacturing;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import static simu.manufacturing.Store.*;

/** Finished units remain placed here until Storage commits receiving capacity. */
final class OutputCustody {
 static void begin(Store s,Connection c,Map<String,Object> run,Map<String,Object> order)throws SQLException{
  if(!run.get("mode").equals("helics"))return;
  UUID unitId=uuid5(uuid(order.get("id")),"handling-output");var unit=one(c,"SELECT * FROM production_handling_units WHERE id=?",unitId);
  if(unit==null||!unit.get("state").equals("available")||unit.get("position")==null)throw new Conflict("Finished output requires confirmed source placement");
  var position=unit.get("position").toString();int cell=Integer.parseInt(position.substring("manufacturing.cell".length(),"manufacturing.cell".length()+2));
  String destination=s.settings.get("STORAGE_FINISHED_ENDPOINT","storage.finished_receipt.dock%02d".formatted(cell));
  if(!Custody.location(Json.M.valueToTree(destination),"storage","finished").path("kind").asText().equals("dock")||!destination.startsWith("storage.finished_receipt."))throw new Conflict("Finished output requires a Storage receiving dock");
  sql(c,"UPDATE production_handling_units SET state='reserved',version=version+1 WHERE id=?",unitId);
  UUID id=uuid5(unitId,"storage-custody");var h=Json.M.createObjectNode();h.put("id",id.toString());h.put("run_id",run.get("id").toString());h.put("epoch",run.get("epoch").toString());h.put("source","manufacturing");h.put("destination_owner","storage");h.put("origin",position);h.put("destination",destination);h.put("state","offered");h.set("unit",Json.M.valueToTree(HandlingUnits.unit(one(c,"SELECT * FROM production_handling_units WHERE id=?",unitId))));for(var field:List.of("departure_token","receipt_id","reason"))h.putNull(field);
  sql(c,"INSERT INTO production_output_custody(id,run_id,epoch,unit_id,batch_id,correlation_id,state,offer) VALUES (?,?,?,?,?,?,'offered',?::jsonb)",id,run.get("id"),run.get("epoch"),unitId,order.get("id"),order.get("correlation_id"),Json.write(h));publish(s,c,run,h,order.get("correlation_id"));
 }
 static ObjectNode validate(JsonNode event){
  var header=(ObjectNode)event.deepCopy();header.put("type","sample.completed.v1");header.set("payload",Json.parse("{\"quantity\":1}"));Policy.envelope(header);
  var h=event.path("payload");Custody.complete(h,"id","run_id","epoch","source","destination_owner","origin","destination","state","unit","departure_token","receipt_id","reason");for(var key:List.of("id","run_id","epoch"))Policy.uuid(h.get(key));
  var u=h.path("unit");Custody.complete(u,"id","barcode","run_id","epoch","contents","category","state","owner","version","custody_generation","last_sequence","position","origin","destination","handoff_id");UUID unit=Policy.uuid(u.get("id"));
  String state=h.path("state").asText();if(!Set.of("accepted","received").contains(state)||!event.path("type").asText().equals("handling."+state+".v1")||!h.path("source").asText().equals("manufacturing")||!h.path("destination_owner").asText().equals("storage")||!u.path("owner").asText().equals("manufacturing")||!u.path("category").asText().equals("finished")||!event.path("source").asText().equals("storage")||!event.path("destination").asText().equals("manufacturing")||!event.path("boundary").asText().equals("materials"))throw new Conflict("Unsupported finished-output custody route");
  for(var key:List.of("run_id","epoch"))if(!event.path(key).equals(h.path(key))||!u.path(key).equals(h.path(key)))throw new Conflict("Output custody scope changed");
  int version=Policy.integer(u.get("version"),1,Integer.MAX_VALUE),sequence=Policy.integer(u.get("last_sequence"),0,Integer.MAX_VALUE),generation=Policy.integer(u.get("custody_generation"),0,Integer.MAX_VALUE);
  if(!event.path("aggregate_id").equals(h.path("id"))||!event.path("causation_id").equals(h.path("id"))||event.path("aggregate_version").asInt()!=version||!u.path("barcode").asText().equals("HU-"+unit.toString().replace("-","").toUpperCase(Locale.ROOT)))throw new Conflict("Output custody identity changed");
  if(!u.path("contents").isArray()||u.path("contents").size()!=1)throw new IllegalArgumentException("One complete output SKU required");var item=u.path("contents").get(0);Custody.complete(item,"sku","quantity");Production.code(item.get("sku"));Policy.integer(item.get("quantity"),1,10000);
  if(!Custody.location(h.get("origin"),"manufacturing","finished").path("kind").asText().equals("cell_output")||!Custody.location(h.get("destination"),"storage","finished").path("kind").asText().equals("dock")||!h.path("destination").asText().startsWith("storage.finished_receipt."))throw new Conflict("Finished custody requires production output and Storage receipt endpoints");
  if(!h.path("reason").isNull())throw new Conflict("Positive output custody proof cannot carry a rejection reason");
  if(state.equals("accepted")){
   if(version>Integer.MAX_VALUE-2||sequence>Integer.MAX_VALUE-2||generation>Integer.MAX_VALUE-1||!u.path("state").asText().equals("reserved")||!u.path("position").equals(h.path("origin"))||!u.path("origin").isNull()||!u.path("destination").isNull()||!u.path("handoff_id").isNull()||!h.path("departure_token").isNull()||!h.path("receipt_id").isNull())throw new Conflict("Output acceptance requires unchanged placed reserved unit");
  }else{Policy.uuid(h.get("receipt_id"));var token=h.path("departure_token");Custody.complete(token,"id","handoff_id","unit_id","run_id","epoch","custody_generation","last_sequence","unit_version");Policy.uuid(token.get("id"));if(version==Integer.MAX_VALUE||sequence<1||generation<1||!u.path("state").asText().equals("in_transit")||!u.path("position").isNull()||!u.path("origin").equals(h.path("origin"))||!u.path("destination").equals(h.path("destination"))||!u.path("handoff_id").equals(h.path("id"))||!token.path("unit_id").equals(u.path("id"))||!token.path("handoff_id").equals(h.path("id"))||!token.path("unit_version").equals(u.path("version")))throw new Conflict("Output receipt requires matching departure proof");for(var key:List.of("run_id","epoch","last_sequence","custody_generation"))if(!token.path(key).equals(u.path(key)))throw new Conflict("Output departure token changed");}
  return (ObjectNode)h;
 }
 static String ingest(Store s,JsonNode event,String endpoint){validate(event);var peer=s.settings.peers.path("materials");if(!s.settings.providers.path("materials").asText().equals("helics")||!peer.path("source").asText().equals("storage")||!peer.path("endpoint").asText().equals(endpoint)||!event.path("federation_id").asText().equals(s.settings.federation))throw new Conflict("Unconfigured output custody peer");
  return s.tx(c->{var run=current(c);if(!event.path("run_id").asText().equals(run.get("id").toString())||!event.path("epoch").asText().equals(run.get("epoch").toString()))return "fenced";var old=one(c,"SELECT * FROM production_custody_events WHERE event_id=?",Policy.uuid(event.get("event_id")));if(old!=null){if(!json(old.get("envelope")).equals(event))throw new Conflict("Output event identity changed");if(Set.of("running","held").contains(run.get("state")))replay(c,run,event);return "duplicate";}
   if(!Set.of("running","held").contains(run.get("state")))throw new Conflict("Inactive output custody run");UUID id=UUID.randomUUID();double due=Math.max(number(run,"granted"),event.path("effective_time").asDouble());sql(c,"INSERT INTO jobs(id,run_id,epoch,idempotency_key,due_at,original_due_at,payload) VALUES (?,?,?,?,?,?,?::jsonb)",id,run.get("id"),run.get("epoch"),"boundary:"+event.path("event_id").asText(),due,event.path("effective_time").asDouble(),Json.write(Map.of("output_custody",event)));sql(c,"INSERT INTO production_commands(id,run_id,command) VALUES (?,?,?::jsonb)",id,run.get("id"),Json.write(Map.of("action","output_custody","handoff_id",event.path("aggregate_id").asText())));sql(c,"INSERT INTO production_custody_events VALUES (?,?,?::jsonb,?)",Policy.uuid(event.get("event_id")),run.get("id"),Json.write(event),id);return "accepted";
  });
 }
 static String execute(Store s,Connection c,Map<String,Object> run,Map<String,Object> job)throws SQLException{
  var save=c.setSavepoint();try{apply(s,c,run,job,json(job.get("payload")).path("output_custody"));sql(c,"UPDATE production_commands SET status='completed',reason=NULL WHERE id=?",job.get("id"));}catch(Conflict|IllegalArgumentException error){c.rollback(save);sql(c,"UPDATE production_commands SET status='rejected',reason=? WHERE id=?",error.getMessage(),job.get("id"));}sql(c,"UPDATE jobs SET status='completed',error=NULL WHERE id=?",job.get("id"));return "completed";
 }
 static void apply(Store s,Connection c,Map<String,Object> run,Map<String,Object> job,JsonNode e)throws SQLException{
  var h=validate(e);var row=one(c,"SELECT * FROM production_output_custody WHERE id=? AND run_id=? AND epoch=?",Policy.uuid(h.get("id")),run.get("id"),run.get("epoch"));if(row==null||!row.get("correlation_id").toString().equals(e.path("correlation_id").asText()))throw new Conflict("Unknown or changed output custody");
  if(h.path("state").asText().equals("accepted")){
   var expected=(ObjectNode)json(row.get("offer")).deepCopy();expected.put("state","accepted");if(!expected.equals(h))throw new Conflict("Output acceptance changed immutable offer");if(!row.get("state").equals("offered"))return;
   var unit=one(c,"SELECT * FROM production_handling_units WHERE id=?",row.get("unit_id"));if(!Json.M.valueToTree(HandlingUnits.unit(unit)).equals(h.path("unit")))throw new Conflict("Finished source placement changed");
   sql(c,"UPDATE production_handling_units SET state='in_transit',origin=position,position=NULL,destination=?,handoff_id=?,version=version+1,last_sequence=last_sequence+1,custody_generation=custody_generation+1 WHERE id=?",h.path("destination").asText(),row.get("id"),row.get("unit_id"));var transit=Json.M.valueToTree(HandlingUnits.unit(one(c,"SELECT * FROM production_handling_units WHERE id=?",row.get("unit_id"))));
   var refs=new LinkedHashMap<String,Object>();refs.put("transfer_id",null);refs.put("batch_id",row.get("batch_id"));refs.put("shipment_id",null);
   sql(c,"INSERT INTO production_unit_movements(id,unit_id,barcode,run_id,epoch,sequence,custody_generation,action,origin,destination,simulation_time,\"references\") VALUES (?,?,?,?,?,?,?,'depart',?,?,?,?::jsonb)",uuid5(uuid(row.get("id")),"departure-movement"),row.get("unit_id"),unit.get("barcode"),run.get("id"),run.get("epoch"),transit.path("last_sequence").asInt(),transit.path("custody_generation").asInt(),h.path("origin").asText(),h.path("destination").asText(),run.get("granted"),Json.write(refs));
   var departed=h.deepCopy();departed.put("state","departed");departed.set("unit",transit);departed.set("departure_token",Json.M.valueToTree(Map.of("id",uuid5(uuid(row.get("id")),"departure-token"),"handoff_id",row.get("id"),"unit_id",row.get("unit_id"),"run_id",run.get("id"),"epoch",run.get("epoch"),"custody_generation",transit.path("custody_generation").asInt(),"last_sequence",transit.path("last_sequence").asInt(),"unit_version",transit.path("version").asInt())));sql(c,"UPDATE production_output_custody SET state='departed',departure=?::jsonb WHERE id=?",Json.write(departed),row.get("id"));publish(s,c,run,departed,row.get("correlation_id"));return;
  }
  if(row.get("departure")==null)throw new Conflict("Output receipt preceded committed departure");var check=h.deepCopy();check.put("state","departed");check.putNull("receipt_id");if(!check.equals(json(row.get("departure"))))throw new Conflict("Output receipt changed committed departure");var ack=h.deepCopy();ack.put("state","acknowledged");if(row.get("acknowledgement")!=null){if(!ack.equals(json(row.get("acknowledgement"))))throw new Conflict("Output receipt identity changed");return;}
  var current=one(c,"SELECT * FROM production_handling_units WHERE id=?",row.get("unit_id"));if(!Json.M.valueToTree(HandlingUnits.unit(current)).equals(h.path("unit")))throw new Conflict("Late output receipt cannot retire newer custody");sql(c,"UPDATE production_handling_units SET state='dispatched',version=version+1 WHERE id=?",row.get("unit_id"));sql(c,"UPDATE production_output_custody SET state='acknowledged',acknowledgement=?::jsonb WHERE id=?",Json.write(ack),row.get("id"));publish(s,c,run,ack,row.get("correlation_id"));
 }
 static void publish(Store s,Connection c,Map<String,Object> run,JsonNode h,Object correlation)throws SQLException{
  UUID id=uuid5(Policy.uuid(h.get("id")),"manufacturing:"+h.path("state").asText());var e=Json.M.createObjectNode();e.put("schema_version","1.0");e.put("type","handling."+h.path("state").asText()+".v1");e.put("event_id",id.toString());e.put("federation_id",s.settings.federation);e.put("run_id",run.get("id").toString());e.put("epoch",run.get("epoch").toString());e.put("correlation_id",correlation.toString());e.set("causation_id",h.get("id"));e.set("aggregate_id",h.get("id"));e.put("aggregate_version",h.path("unit").path("version").asInt());e.put("source","manufacturing");e.put("destination","storage");e.put("boundary","supply");e.put("effective_time",number(run,"granted")+s.settings.quantum);e.put("wall_time",Instant.now().toString());e.put("quantity_unit","item");e.set("payload",h);sql(c,"INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (?,?,?::jsonb) ON CONFLICT(id) DO NOTHING",id,run.get("id"),Json.write(e));
 }
 static List<JsonNode> snapshot(Connection c,Map<String,Object> run)throws SQLException{var result=new ArrayList<JsonNode>();for(var row:rows(c,"SELECT * FROM production_output_custody WHERE run_id=? AND epoch=? ORDER BY id",run.get("id"),run.get("epoch")))result.add(json(row.get(row.get("acknowledgement")!=null?"acknowledgement":row.get("departure")!=null?"departure":"offer")));return result;}
 static int recover(Connection c,Map<String,Object> run)throws SQLException{if(!Set.of("running","held").contains(run.get("state")))return 0;var pending=rows(c,"SELECT DISTINCT b.envelope FROM boundary_outbox b JOIN production_output_custody h ON h.id::text=b.envelope->'payload'->>'id' AND h.state=b.envelope->'payload'->>'state' WHERE h.run_id=? AND h.epoch=? AND h.state IN ('offered','departed') AND b.run_id=? AND NOT EXISTS(SELECT 1 FROM boundary_outbox n WHERE n.run_id=b.run_id AND n.envelope->>'event_id'=b.envelope->>'event_id' AND (n.sent_at IS NULL OR n.sent_at>clock_timestamp()-interval '5 seconds'))",run.get("id"),run.get("epoch"),run.get("id"));for(var row:pending)sql(c,"INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (?,?,?::jsonb)",UUID.randomUUID(),run.get("id"),Json.write(row.get("envelope")));return pending.size();}
 static void replay(Connection c,Map<String,Object> run,JsonNode e)throws SQLException{String stage=e.path("type").asText().equals("handling.accepted.v1")?"departed":"acknowledged";UUID id=uuid5(Policy.uuid(e.get("aggregate_id")),"manufacturing:"+stage);var old=one(c,"SELECT envelope FROM boundary_outbox b WHERE b.run_id=? AND b.envelope->>'event_id'=? AND NOT EXISTS(SELECT 1 FROM boundary_outbox n WHERE n.run_id=b.run_id AND n.envelope->>'event_id'=b.envelope->>'event_id' AND (n.sent_at IS NULL OR n.sent_at>clock_timestamp()-interval '5 seconds')) LIMIT 1",run.get("id"),id.toString());if(old!=null)sql(c,"INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (?,?,?::jsonb)",UUID.randomUUID(),run.get("id"),Json.write(old.get("envelope")));}
}
